INSERT INTO `config_info` VALUES (5, 'jeecg-dev-satoken.yaml', 'DEFAULT_GROUP', '################ Cấu hình Sa-Token (Tài liệu: https://sa-token.cc) ################\nsa-token:\n  # Tên token (đồng thời cũng là tên cookie)\n  token-name: X-Access-Token\n  # Thời hạn hiệu lực token (đơn vị: giây) Mặc định 30 ngày, -1 nghĩa là hiệu lực vĩnh viễn\n  timeout: 2592000\n  # Tần suất hoạt động tối thiểu của token (đơn vị: giây), nếu token quá thời gian này không truy cập hệ thống sẽ bị đóng băng, mặc định -1 nghĩa là không giới hạn, không bao giờ đóng băng\n  active-timeout: -1\n  # Có cho phép cùng một tài khoản đăng nhập đồng thời ở nhiều nơi không (khi là true thì cho phép đăng nhập cùng lúc, khi là false thì lần đăng nhập mới sẽ đẩy lần đăng nhập cũ ra)\n  is-concurrent: false\n  # Khi nhiều người đăng nhập cùng một tài khoản, có dùng chung một token không (khi là true thì mọi lần đăng nhập dùng chung một token, khi là false thì mỗi lần đăng nhập tạo một token mới)\n  is-share: false\n  # Phong cách token (dùng jwt-simple để giữ định dạng giống token JWT gốc)\n  token-style: jwt-simple\n  # Có xuất nhật ký thao tác không\n  is-log: false\n  # Có đọc token từ cookie không\n  is-read-cookie: false\n  # Có đọc token từ head không\n  is-read-header: true\n  # Có đọc token từ thân yêu cầu (tham số URL) không\n  is-read-body: true\n  # Khóa bí mật jwt (Quan trọng: vui lòng đổi thành khóa bí mật của bạn, đảm bảo đủ phức tạp)\n  jwt-secret-key: \"dd05f1c54d63749eda95f9fa6d49v442a\"\n  \nspring:\n  datasource:\n    druid:\n      stat-view-servlet:\n        enabled: true\n        loginUsername: admin\n        loginPassword: 123456\n        allow:\n      web-stat-filter:\n        enabled: true\n    dynamic:\n      druid:\n        initial-size: 5\n        min-idle: 5\n        maxActive: 20\n        maxWait: 60000\n        timeBetweenEvictionRunsMillis: 60000\n        minEvictableIdleTimeMillis: 300000\n        validationQuery: SELECT 1 FROM DUAL\n        testWhileIdle: true\n      