-- ----------------------------
-- Table structure for group_capacity
-- ----------------------------
DROP TABLE IF EXISTS `group_capacity`;
CREATE TABLE `group_capacity`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID khóa chính',
  `group_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'Group ID, ký tự rỗng nghĩa là toàn bộ cụm',
  `quota` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Hạn mức, 0 nghĩa là dùng giá trị mặc định',
  `usage` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Lượng sử dụng',
  `max_size` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Giới hạn tối đa kích thước một cấu hình, đơn vị byte, 0 nghĩa là dùng giá trị mặc định',
  `max_aggr_count` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Số lượng tối đa cấu hình con tổng hợp, 0 nghĩa là dùng giá trị mặc định',
  `max_aggr_size` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Giới hạn tối đa kích thước cấu hình con của một dữ liệu tổng hợp, đơn vị byte, 0 nghĩa là dùng giá trị mặc định',
  `max_history_count` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Số lượng tối đa lịch sử thay đổi',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Thời gian tạo',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Thời gian sửa đổi',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_group_id`(`group_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Bảng thông tin dung lượng cụm, từng Group' ROW_FORMAT = DYNAMIC;

