INSERT INTO `his_config_info` VALUES (4, 9, 'jeecg-dev.yaml', 'DEFAULT_GROUP', '', 'spring:\r\n  datasource:\r\n    druid:\r\n      stat-view-servlet:\r\n        enabled: true\r\n        loginUsername: admin\r\n        loginPassword: 123456\r\n        allow:\r\n      web-stat-filter:\r\n        enabled: true\r\n    dynamic:\r\n      druid:\r\n        initial-size: 5\r\n        min-idle: 5\r\n        maxActive: 20\r\n        maxWait: 60000\r\n        timeBetweenEvictionRunsMillis: 60000\r\n        minEvictableIdleTimeMillis: 300000\r\n        validationQuery: SELECT 1 FROM DUAL\r\n        testWhileIdle: true\r\n        testOnBorrow: false\r\n        testOnReturn: false\r\n        poolPreparedStatements: true\r\n        maxPoolPreparedStatementPerConnectionSize: 20\r\n        filters: stat,slf4j\r\n        wall:\r\n          selectWhereAlwayTrueCheck: false\r\n        stat:\r\n          merge-sql: true\r\n          slow-sql-millis: 5000\r\n      datasource:\r\n        master:\r\n          url: jdbc:mysql://jeecg-boot-mysql:3306/jeecg-boot?characterEncoding=UTF-8&useUnicode=true&useSSL=false&tinyInt1isBit=false&allowPublicKeyRetrieval=true&serverTimezone=Asia/Shanghai\r\n          username: root\r\n          password: root\r\n          driver-class-name: com.mysql.cj.jdbc.Driver\r\n        # sharding-db:\r\n        #  driver-class-name: org.apache.shardingsphere.driver.ShardingSphereDriver\r\n        #  url: jdbc:shardingsphere:nacos:sharding.yaml?serverAddr=${spring.cloud.nacos.config.server-addr}&namespace=${spring.cloud.nacos.config.namespace}&group=${spring.cloud.nacos.config.group}\r\n  data:\r\n    redis:\r\n      database: 0\r\n      host: jeecg-boot-redis\r\n      password:\r\n      port: 6379\r\n  rabbitmq:\r\n    host: jeecg-boot-rabbitmq\r\n    username: guest\r\n    password: guest\r\n    port: 5672\r\n    publisher-confirms: true\r\n    publisher-returns: true\r\n    virtual-host: /\r\n    listener:\r\n      simple:\r\n        acknowledge-mode: manual\r\n        concurrency: 1\r\n        max-concurrency: 1\r\n        retry:\r\n          enabled: true\r\n  flyway:\r\n    enabled: false\r\n    locations: classpath:flyway/sql/mysql\r\n    clean-disabled: true\r\nminidao:\r\n  base-package: org.jeecg.modules.jmreport.*,org.jeecg.modules.drag.*\r\njeecg:\r\n  firewall:\r\n    dataSourceSafe: false\r\n    lowCodeMode: dev\r\n  signatureSecret: dd05f1c54d63749eda95f9fa6d49v442a\r\n  signUrls: /sys/dict/getDictItems/*,/sys/dict/loadDict/*,/sys/dict/loadDictOrderByValue/*,/sys/dict/loadDictItem/*,/sys/dict/loadTreeData,/sys/api/queryTableDictItemsByCode,/sys/api/queryFilterTableDictInfo,/sys/api/queryTableDictByKeys,/sys/api/translateDictFromTable,/sys/api/translateDictFromTableByKeys\r\n  uploadType: local\r\n  domainUrl:\r\n    pc: http://localhost:3100\r\n    app: http://localhost:8051\r\n  path:\r\n    upload: /opt/upFiles\r\n    webapp: /opt/webapp\r\n  shiro:\r\n    excludeUrls: /test/jeecgDemo/demo3,/test/jeecgDemo/redisDemo/**,/category/**,/visual/**,/map/**,/jmreport/bigscreen2/**\r\n  oss:\r\n    endpoint: oss-cn-beijing.aliyuncs.com\r\n    accessKey: ??\r\n    secretKey: ??\r\n    bucketName: jeecgdev\r\n    staticDomain: ??  \r\n  file-view-domain: 127.0.0.1:8012\r\n  minio:\r\n    minio_url: http://minio.jeecg.com\r\n    minio_name: ??\r\n    minio_pass: ??\r\n    bucketName: otatest\r\n  jmreport:\r\n    saasMode:\r\n    firewall:\r\n      dataSourceSafe: false\r\n      lowCodeMode: dev\r\n  wps:\r\n    domain: https://wwo.wps.cn/office/\r\n    appid: ??\r\n    appsecret: ??\r\n  xxljob:\r\n    enabled: true\r\n    adminAddresses: http://jeecg-boot-xxljob:9080\r\n    appname: ${spring.application.name}\r\n    accessToken: \'\'\r\n    logPath: logs/jeecg/job/jobhandler/\r\n    logRetentionDays: 30\r\n  redisson:\r\n    address: jeecg-boot-redis:6379\r\n    password:\r\n    type: STANDALONE\r\n    enabled: true\r\n  ai-chat:\r\n    enabled: false\r\n    apiKey: \"？？？？\"\r\n    apiHost: \"https://api.openai.com\"\r\n    timeout: 60\r\n  ai-rag:\r\n    embed-store:\r\n      host: 127.0.0.1\r\n      port: 5432\r\n      database: postgres\r\n      user: postgres\r\n      password: postgres\r\n      table: embeddings\r\ncas:\r\n  prefixUrl: http://localhost:8888/cas\r\nknife4j:\r\n  production: false\r\n  basic:\r\n    enable: false\r\n    username: jeecg\r\n    password: jeecg1314\r\njustauth:\r\n  enabled: true\r\n  type:\r\n    GITHUB:\r\n      client-id: ??\r\n      client-secret: ??\r\n      redirect-uri: http://sso.test.com:8080/jeecg-boot/thirdLogin/github/callback\r\n    WECHAT_ENTERPRISE:\r\n      client-id: ??\r\n      client-secret: ??\r\n      redirect-uri: http://sso.test.com:8080/jeecg-boot/thirdLogin/wechat_enterprise/callback\r\n      agent-id: ??\r\n    DINGTALK:\r\n      client-id: ??\r\n      client-secret: ??\r\n      redirect-uri: http://sso.test.com:8080/jeecg-boot/thirdLogin/dingtalk/callback\r\n  cache:\r\n    type: default\r\n    prefix: \'demo::\'\r\n    timeout: 1h\r\nthird-app:\r\n  enabled: false\r\n  type:\r\n    WECHAT_ENTERPRISE:\r\n      enabled: false\r\n      client-id: ??\r\n      client-secret: ??\r\n      agent-id: ??\r\n    DINGTALK:\r\n      enabled: false\r\n      client-id: ??\r\n      client-secret: ??\r\n      agent-id: ??', '3c0bb9da0a7bf310132e6826ea00b3ef', '2026-08-10 11:59:03', '2026-08-10 11:59:04', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'public', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` VALUES (6, 10, 'jeecg-dev-satoken.yaml', 'DEFAULT_GROUP', '', '################ Cấu hình Sa-Token (Tài liệu: https://sa-token.cc) ################\r\nsa-token:\r\n  # Tên token (đồng thời cũng là tên cookie)\r\n  token-name: X-Access-Token\r\n  # Thời hạn hiệu lực token (đơn vị: giây) Mặc định 30 ngày, -1 nghĩa là hiệu lực vĩnh viễn\r\n  timeout: 2592000\r\n  # Tần suất hoạt động tối thiểu của token (đơn vị: giây), nếu token quá thời gian này không truy cập hệ thống sẽ bị đóng băng, mặc định -1 nghĩa là không giới hạn, không bao giờ đóng băng\r\n  active-timeout: -1\r\n  # Có cho phép cùng một tài khoản đăng nhập đồng thời ở nhiều nơi không (khi là true thì cho phép đăng nhập cùng lúc, khi là false thì lần đăng nhập mới sẽ đẩy lần đăng nhập cũ ra)\r\n  is-concurrent: false\r\n  # Khi nhiều người đăng nhập cùng một tài khoản, có dùng chung một token không (khi là true thì mọi lần đăng nhập dùng chung một token, khi là false thì mỗi lần đăng nhập tạo một token mới)\r\n  is-share: false\r\n  # Phong cách token (dùng jwt-simple để giữ định dạng giống token JWT gốc)\r\n  token-style: jwt-simple\r\n  # Có xuất nhật ký thao tác không\r\n  is-log: false\r\n  # Có đọc token từ cookie không\r\n  is-read-cookie: false\r\n  # Có đọc token từ head không\r\n  is-read-header: true\r\n  # Có đọc token từ thân yêu cầu (tham số URL) không\r\n  is-read-body: true\r\n  # Khóa bí mật jwt (Quan trọng: vui lòng đổi thành khóa bí mật của bạn, đảm bảo đủ phức tạp)\r\n  jwt-secret-key: \"dd05f1c54d63749eda95f9fa6d49v442a\"\r\n  \r\nspring:\r\n  datasource:\r\n    druid:\r\n      stat-view-servlet:\r\n        enabled: true\r\n        loginUsername: admin\r\n        loginPassword: 123456\r\n        allow:\r\n      web-stat-filter:\r\n        enabled: true\r\n    dynamic:\r\n      druid:\r\n        initial-size: 5\r\n        min-idle: 5\r\n        maxActive: 20\r\n        maxWait: 60000\r\n        timeBetweenEvictionRunsMillis: 60000\r\n        minEvictableIdleTimeMillis: 300000\r\n        validationQuery: SELECT 1 FROM DUAL\r\n        testWhileIdle: true\r\n        testOnBorrow: false\r\n        testOnReturn: false\r\n        poolPreparedStatements: true\r\n        maxPoolPreparedStatementPerConnectionSize: 20\r\n        filters: stat,slf4j\r\n        wall:\r\n          selectWhereAlwayTrueCheck: false\r\n        stat:\r\n          merge-sql: true\r\n          slow-sql-millis: 5000\r\n      datasource:\r\n        master:\r\n          url: jdbc:mysql://jeecg-boot-mysql:3306/jeecg-boot?characterEncoding=UTF-8&useUnicode=true&useSSL=false&tinyInt1isBit=false&allowPublicKeyRetrieval=true&serverTimezone=Asia/Shanghai\r\n          username: root\r\n          password: root\r\n          driver-class-name: com.mysql.cj.jdbc.Driver\r\n        # sharding-db:\r\n        #  driver-class-name: org.apache.shardingsphere.driver.ShardingSphereDriver\r\n        #  url: jdbc:shardingsphere:nacos:sharding.yaml?serverAddr=${spring.cloud.nacos.config.server-addr}&namespace=${spring.cloud.nacos.config.namespace}&group=${spring.cloud.nacos.config.group}\r\n  data:\r\n    redis:\r\n      database: 0\r\n      host: jeecg-boot-redis\r\n      password:\r\n      port: 6379\r\n  rabbitmq:\r\n    host: jeecg-boot-rabbitmq\r\n    username: guest\r\n    password: guest\r\n    port: 5672\r\n    publisher-confirms: true\r\n    publisher-returns: true\r\n    virtual-host: /\r\n    listener:\r\n      simple:\r\n        acknowledge-mode: manual\r\n        concurrency: 1\r\n        max-concurrency: 1\r\n        retry:\r\n          enabled: true\r\n  flyway:\r\n    enabled: false\r\n    locations: classpath:flyway/sql/mysql\r\n    clean-disabled: true\r\nminidao:\r\n  base-package: org.jeecg.modules.jmreport.*,org.jeecg.modules.drag.*\r\njeecg:\r\n  firewall:\r\n    dataSourceSafe: false\r\n    lowCodeMode: dev\r\n  signatureSecret: dd05f1c54d63749eda95f9fa6d49v442a\r\n  signUrls: /sys/dict/getDictItems/*,/sys/dict/loadDict/*,/sys/dict/loadDictOrderByValue/*,/sys/dict/loadDictItem/*,/sys/dict/loadTreeData,/sys/api/queryTableDictItemsByCode,/sys/api/queryFilterTableDictInfo,/sys/api/queryTableDictByKeys,/sys/api/translateDictFromTable,/sys/api/translateDictFromTableByKeys\r\n  uploadType: local\r\n  domainUrl:\r\n    pc: http://localhost:3100\r\n    app: http://localhost:8051\r\n  path:\r\n    upload: /opt/upFiles\r\n    webapp: /opt/webapp\r\n  shiro:\r\n    excludeUrls: /test/jeecgDemo/demo3,/test/jeecgDemo/redisDemo/**,/category/**,/visual/**,/map/**,/jmreport/bigscreen2/**\r\n  oss:\r\n    endpoint: oss-cn-beijing.aliyuncs.com\r\n    accessKey: ??\r\n    secretKey: ??\r\n    bucketName: jeecgdev\r\n    staticDomain: ??  \r\n  file-view-domain: 127.0.0.1:8012\r\n  minio:\r\n    minio_url: http://minio.jeecg.com\r\n    minio_name: ??\r\n    minio_pass: ??\r\n    bucketName: otatest\r\n  jmreport:\r\n    saasMode:\r\n    firewall:\r\n      dataSourceSafe: false\r\n      lowCodeMode: dev\r\n  wps:\r\n    domain: https://wwo.wps.cn/office/\r\n    appid: ??\r\n    appsecret: ??\r\n  xxljob:\r\n    enabled: false\r\n    adminAddresses: http://jeecg-boot-xxljob:9080/xxl-job-admin\r\n    appname: ${spring.application.name}\r\n    accessToken: \'\'\r\n    logPath: logs/jeecg/job/jobhandler/\r\n    logRetentionDays: 30\r\n  redisson:\r\n    address: jeecg-boot-redis:6379\r\n    password:\r\n    type: STANDALONE\r\n    enabled: true\r\n  ai-chat:\r\n    enabled: false\r\n    apiKey: \"？？？？\"\r\n    apiHost: \"https://api.openai.com\"\r\n    timeout: 60\r\n  ai-rag:\r\n    embed-store:\r\n      host: 127.0.0.1\r\n      port: 5432\r\n      database: postgres\r\n      user: postgres\r\n      password: postgres\r\n      table: embeddings\r\ncas:\r\n  prefixUrl: http://localhost:8888/cas\r\nknife4j:\r\n  production: false\r\n  basic:\r\n    enable: false\r\n    username: jeecg\r\n    password: jeecg1314\r\njustauth:\r\n  enabled: true\r\n  type:\r\n    GITHUB:\r\n      client-id: ??\r\n      client-secret: ??\r\n      redirect-uri: http://sso.test.com:8080/jeecg-boot/thirdLogin/github/callback\r\n    WECHAT_ENTERPRISE:\r\n      client-id: ??\r\n      client-secret: ??\r\n      redirect-uri: http://sso.test.com:8080/jeecg-boot/thirdLogin/wechat_enterprise/callback\r\n      agent-id: ??\r\n    DINGTALK:\r\n      client-id: ??\r\n      client-secret: ??\r\n      redirect-uri: http://sso.test.com:8080/jeecg-boot/thirdLogin/dingtalk/callback\r\n  cache:\r\n    type: default\r\n    prefix: \'demo::\'\r\n    timeout: 1h\r\nthird-app:\r\n  enabled: false\r\n  type:\r\n    WECHAT_ENTERPRISE:\r\n      enabled: false\r\n      client-id: ??\r\n      client-secret: ??\r\n      agent-id: ??\r\n    DINGTALK:\r\n      enabled: false\r\n      client-id: ??\r\n      client-secret: ??\r\n      agent-id: ??', '1c1b20938e6641f1c9a5c0ea94a0c1bd', '2026-08-10 11:59:20', '2026-08-10 11:59:20', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'public', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');

-- ----------------------------
-- Table structure for permissions
-- ----------------------------
DROP TABLE IF EXISTS `permissions`;
CREATE TABLE `permissions`  (
  `role` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'role',
  `resource` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'resource',
  `action` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'action',
  UNIQUE INDEX `uk_role_permission`(`role`, `resource`, `action`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of permissions
-- ----------------------------

-- ----------------------------
-- Table structure for pipeline_execution
-- ----------------------------
DROP TABLE IF EXISTS `pipeline_execution`;
CREATE TABLE `pipeline_execution`  (
  `execution_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ID thực thi',
  `resource_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Loại tài nguyên',
  `resource_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Tên tài nguyên',
  `namespace_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'ID namespace',
  `version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Phiên bản',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Trạng thái thực thi',
  `pipeline` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON kết quả node pipeline',
  `create_time` bigint(20) NOT NULL COMMENT 'Thời gian tạo',
  `update_time` bigint(20) NOT NULL COMMENT 'Thời gian sửa đổi',
  PRIMARY KEY (`execution_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Bản ghi thực thi Pipeline xét duyệt phát hành tài nguyên AI' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of pipeline_execution
-- ----------------------------

-- ----------------------------
-- Table structure for roles
